"""
e7_realworld.py — Case study on real-world iptables rulesets (Diekmann et al., BSD-3 licence).
Input : data/realworld/*.txt   (simple-firewall dumps: "ACTION proto -- src dst [proto dpt(s):x[:y]] [spt(s):x[:y]]")
Steps : parse -> listed-rule policy over the 5-tuple -> canonical Tree-Rule (FDD-style, several field orders)
        -> reconstruct with IDQ+witnesses (Theorem 2b learner) -> certificate size (Theorem 3) -> table.
Output: results/E7_realworld.csv, results/fig_E7.png
Usage : python e7_realworld.py            (≈ 1–10 min)
"""
import os, re, sys, csv, math, random, time, glob, itertools
from functools import lru_cache
try:
    sys.stdout.reconfigure(encoding="utf-8")
except Exception:
    pass
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from a1sim import TreeRule, TRNode, ListedRule, Oracle, learn_tr_idq, audit_certificate

HERE = os.path.dirname(os.path.abspath(__file__))
DATA = os.path.join(HERE, "data", "realworld")

# ---- embedded dataset (Diekmann et al., BSD-3; extracted on first run if data/realworld is missing) ----
_EMBEDDED = """"""

def _ensure_data():
    if glob.glob(os.path.join(DATA, "*.txt")):
        return
    import base64, zlib, io, tarfile
    os.makedirs(DATA, exist_ok=True)
    raw = zlib.decompress(base64.b64decode(_EMBEDDED))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r") as tf:
        try:
            tf.extractall(DATA, filter="data")
        except TypeError:
            tf.extractall(DATA)
    print("extracted embedded dataset to", DATA, flush=True)
OUT = os.path.join(HERE, "results"); os.makedirs(OUT, exist_ok=True)
WIDTHS = [32, 32, 8, 16, 16]                       # src, dst, proto, sport, dport
FIELD = {"src": 0, "dst": 1, "proto": 2, "sport": 3, "dport": 4}
W = [1 << w for w in WIDTHS]
PROTO = {"all": None, "tcp": 6, "udp": 17, "icmp": 1, "esp": 50, "ah": 51, "gre": 47, "sctp": 132}


def log(msg):
    print(time.strftime("[%H:%M:%S] ") + msg, flush=True)


# ---------------------------------------------------------------- parsing
def cidr(s):
    if "/" in s:
        ip, pl = s.split("/"); pl = int(pl)
    else:
        ip, pl = s, 32
    a, b, c, d = (int(x) for x in ip.split("."))
    base = (a << 24) | (b << 16) | (c << 8) | d
    if pl == 0:
        return (0, W[0] - 1)
    mask = (0xFFFFFFFF << (32 - pl)) & 0xFFFFFFFF
    lo = base & mask
    return (lo, lo | (~mask & 0xFFFFFFFF))


def portspec(tok):
    v = tok.split(":", 1)[1]
    if ":" in v:
        a, b = v.split(":"); return (int(a), int(b))
    return (int(v), int(v))


def parse_file(path):
    rules = []
    for line in open(path, encoding="utf-8", errors="ignore"):
        t = line.split()
        if len(t) < 5 or t[0] not in ("ACCEPT", "DROP", "REJECT"):
            continue
        action = 1 if t[0] == "ACCEPT" else 0
        proto = t[1]
        src, dst = cidr(t[3]), cidr(t[4])
        pr = PROTO.get(proto)
        if pr is None and proto.isdigit():
            pr = int(proto)
        pbox = (0, 255) if pr is None else (pr, pr)
        sport, dport = (0, 65535), (0, 65535)
        for tok in t[5:]:
            if tok.startswith("dpt"):
                dport = portspec(tok)
            elif tok.startswith("spt"):
                sport = portspec(tok)
        rules.append(([src, dst, pbox, sport, dport], action))
    return rules


# ---------------------------------------------------------------- canonical Tree-Rule (FDD-style, memoised)
def build_tree(rules, order, keep_rule_id=False):
    """Return (leaf_count, root TRNode built as a real tree) for first-match semantics of `rules` under field order."""
    d = len(order)
    boxes = [r[0] for r in rules]; acts = [r[1] for r in rules]

    @lru_cache(maxsize=None)
    def sub(level, idxs):
        """canonical subtree over fields order[level:] for the rules idxs (tuple, priority order kept)."""
        if level == d:
            # first-match: first rule in idxs decides (all rules in idxs intersect region entirely on remaining fields)
            if keep_rule_id:
                return ("L", idxs[0] if idxs else -1)
            return ("L", acts[idxs[0]] if idxs else 0)      # empty: default policy (deny)
        f = order[level]
        # elementary intervals of field f induced by the rules
        cuts = {0, W[f]}
        for i in idxs:
            lo, hi = boxes[i][f]; cuts.add(lo); cuts.add(hi + 1)
        cuts = sorted(cuts)
        kids = []
        for a, b in zip(cuts, cuts[1:]):
            here = tuple(i for i in idxs if boxes[i][f][0] <= a and b - 1 <= boxes[i][f][1])
            kids.append((a, sub(level + 1, here)))
        # merge adjacent equal children
        merged = [kids[0]]
        for a, k in kids[1:]:
            if k == merged[-1][1]:
                continue
            merged.append((a, k))
        return ("N", f, tuple(a for a, _ in merged[1:]), tuple(k for _, k in merged))

    root = sub(0, tuple(range(len(rules))))
    return root


def effective_rules(node, acc=None, seen=None):
    """set of rule indices that decide at least one packet (non-shadowed rules)"""
    acc = set() if acc is None else acc; seen = set() if seen is None else seen
    if id(node) in seen:
        return acc
    seen.add(id(node))
    if node[0] == "L":
        acc.add(node[1])
    else:
        for k in node[3]:
            effective_rules(k, acc, seen)
    return acc


def count_leaves(node, memo=None):
    memo = {} if memo is None else memo
    if id(node) in memo:
        return memo[id(node)]
    if node[0] == "L":
        r = 1
    else:
        r = sum(count_leaves(k, memo) for k in node[3])
    memo[id(node)] = r
    return r


def to_treerule(node, order):
    """Expand canonical (shared) tree into a1sim TreeRule with fields permuted so that depth j tests order[j]."""
    widths = [WIDTHS[f] for f in order]
    t = TreeRule(widths)

    def rec(nd, depth):
        n = TRNode(depth=depth)
        if nd[0] == "L":
            n.depth = len(order); n.action = nd[1]; return n
        # nd tests order[depth] (levels always advance, so nd[1] == order[depth]); it may have a single child (no breaks)
        n.breaks = list(nd[2])
        n.children = [rec(k, depth + 1) for k in nd[3]]
        return n
    t.root = rec(node, 0)
    t._index_leaves()
    return t


def permute(h, order):
    return tuple(h[f] for f in order)


# ---------------------------------------------------------------- main
def main():
    _ensure_data()
    files = sorted(glob.glob(os.path.join(DATA, "*.txt")))
    if not files:
        log("no input files in data/realworld/"); return
    rng = random.Random(7)
    fname = ["src", "dst", "proto", "sport", "dport"]
    heuristic = [[1, 4, 0, 3, 2], [0, 1, 2, 3, 4], [2, 1, 4, 0, 3], [1, 0, 2, 4, 3], [2, 3, 4, 0, 1], [3, 4, 2, 0, 1], [2, 4, 3, 1, 0], [4, 3, 2, 1, 0]]
    rows = []
    for path in files:
        name = os.path.basename(path)[:-4]
        rules = parse_file(path)
        n = len(rules)
        lr = ListedRule(WIDTHS, rules, default=0)
        best = None
        cand = [list(o) for o in itertools.permutations(range(5))] if n <= 300 else heuristic
        for order in cand:
            root = build_tree(rules, order)
            m = count_leaves(root)
            if best is None or m < best[1]:
                best = (",".join(fname[f] for f in order), m, order, root)
        oname, m, order, root = best
        n_orders = len(cand)
        n_eff = len(effective_rules(build_tree(rules, [0, 1, 2, 3, 4], keep_rule_id=True)) - {-1})
        t = to_treerule(root, order)
        assert t.num_leaves() == m
        # semantic check tree vs listed rules on random headers + rule corners
        ok = True
        for _ in range(3000):
            h = tuple(rng.randrange(Wj) for Wj in W)
            if lr.action(h) != t.action(permute(h, order)):
                ok = False; break
        for box, _a in rules[:400]:
            for h in (tuple(lo for lo, hi in box), tuple(hi for lo, hi in box)):
                if lr.action(h) != t.action(permute(h, order)):
                    ok = False
        # reconstruction with IDQ + witnesses (Theorem 2b) — skip if enormous
        q_tree = None
        if m <= 200000:
            wit = t.witnesses(rng)
            orc = Oracle(t)
            t2 = learn_tr_idq(orc, wit, t.widths)
            q_tree = orc.total
            eq = t.equivalent(t2, samples=2000, rng=rng)
        else:
            eq = None
        cert = len(audit_certificate(t)) if m <= 20000 else None
        listed_bound = 2 * n * sum(WIDTHS) + n
        rows.append(dict(ruleset=name, rules=n, effective_rules=n_eff, orders_tried=n_orders, best_order=oname, leaves=m, semantics_ok=ok, tree_probes=q_tree,
                         tree_bound=(m - 1) * 32 + 3 * m - 1, reconstruct_equiv=eq, certificate=cert,
                         listed_disjoint_bound=listed_bound, probes_per_rule=(None if q_tree is None else round(q_tree / n, 1))))
        log(f"{name:28s} n={n:5d} n_eff={n_eff:5d} m={m:7d} order={oname:32s} sem={ok} q_tree={q_tree} cert={cert} eq={eq}")
    with open(os.path.join(OUT, "E7_realworld.csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=rows[0].keys()); w.writeheader(); w.writerows(rows)
    # figure: probes vs rules
    fig, ax = plt.subplots(figsize=(5.2, 3.6))
    rs = [r for r in rows if r["tree_probes"] is not None and r["leaves"] > 1]
    ax.scatter([r["rules"] for r in rs], [r["tree_probes"] for r in rs], s=18, label="Tree-Rule reconstruction, IDQ + witnesses (measured)")
    ax.scatter([r["rules"] for r in rs if r["certificate"] is not None], [r["certificate"] for r in rs if r["certificate"] is not None], s=18, marker="^", label="audit certificate size (Thm 3)")
    xs = sorted(set(r["rules"] for r in rs))
    ax.plot(xs, [2 * x * sum(WIDTHS) + x for x in xs], "r--", lw=1, label="listed-rule bound 209 n (disjoint case)")
    ax.set_xscale("log"); ax.set_yscale("log"); ax.set_xlabel("rules n in the real ruleset"); ax.set_ylabel("packets")
    ax.set_title("Real-world iptables rulesets (E7)"); ax.legend(fontsize=6.5); fig.tight_layout()
    fig.savefig(os.path.join(OUT, "fig_E7.png"), dpi=160)
    log("done")


if __name__ == "__main__":
    main()
